import { FilterDataAccessor } from 'domain/Filter';
import type {
  FilterDataStructure,
  FilterForm,
  FilterValue,
  Option,
} from 'models/Filters';

export const WATERFALL_FILTER_TO_APPLIED_KEY: Record<string, keyof FilterForm> =
  {
    region: 'region',
    brand: 'brands',
    channel: 'channel',
    pack_type: 'pack_type',
    sub_brand: 'sub_brands',
    sku: 'sku',
  };

export const WATERFALL_VIEW_HIERARCHY = [
  'region',
  'channel',
  'brand',
  'sub_brand',
  'pack_type',
  'sku',
] as const;

const PLACEHOLDER_PATTERNS = [/^select a /i, /^select an /i];

const BRAND_DEPENDENT_WATERFALL_VALUES = new Set(['sub_brand', 'sku']);

const BRAND_TIER_WATERFALL_OPTIONS: Option[] = [
  { value: 'sub_brand', label: 'Sub-Brand' },
  { value: 'sku', label: 'SKU' },
];

export const hasSpecificValue = (value?: FilterValue): boolean =>
  Boolean(value && value !== 'All');

const isPlaceholderOption = (option: Option): boolean => {
  if (option.value === 'All') {
    return true;
  }

  const label = String(option.label ?? '');
  return PLACEHOLDER_PATTERNS.some((pattern) => pattern.test(label));
};

export const getSubBrands = (
  dataFilters: FilterDataStructure | undefined,
): Option[] => {
  return (
    dataFilters?.sub_brands?.values.filter(
      (option) => !isPlaceholderOption(option),
    ) ?? []
  );
};
export const countRealSubBrands = (
  dataFilters: FilterDataStructure | undefined,
): number => {
  const values = getSubBrands(dataFilters) ?? [];
  return values.length;
};

export const hasSingleSubBrand = (
  dataFilters: FilterDataStructure | undefined,
  brand?: FilterValue,
): boolean => {
  if (!hasSpecificValue(brand)) {
    return false;
  }

  return countRealSubBrands(dataFilters) === 1;
};

export const getAppliedKeyForWaterfallFilter = (
  waterfallFilter: string,
): keyof FilterForm | undefined =>
  WATERFALL_FILTER_TO_APPLIED_KEY[waterfallFilter];

export const buildPostAppliedForDrill = (
  applied: FilterForm,
  currentView: string,
  clickedLabel: string | string[],
): FilterForm => {
  const appliedKey = getAppliedKeyForWaterfallFilter(currentView);
  if (!appliedKey) {
    return applied;
  }

  const value = Array.isArray(clickedLabel) ? clickedLabel[0] : clickedLabel;

  return {
    ...applied,
    [appliedKey]: value,
  };
};

export const expandRawOptionsWithBrandTier = (
  rawOptions: Option[],
  applied?: FilterForm,
): Option[] => {
  if (!hasSpecificValue(applied?.brands)) {
    return rawOptions;
  }

  const existingValues = new Set(rawOptions.map((option) => option.value));
  const missingBrandTier = BRAND_TIER_WATERFALL_OPTIONS.filter(
    (option) => !existingValues.has(option.value),
  );

  return [...rawOptions, ...missingBrandTier];
};

const sortByWaterfallHierarchy = (options: Option[]): Option[] =>
  [...options].sort((left, right) => {
    const leftIndex = WATERFALL_VIEW_HIERARCHY.indexOf(
      left.value as (typeof WATERFALL_VIEW_HIERARCHY)[number],
    );
    const rightIndex = WATERFALL_VIEW_HIERARCHY.indexOf(
      right.value as (typeof WATERFALL_VIEW_HIERARCHY)[number],
    );

    return (
      (leftIndex === -1 ? Number.MAX_SAFE_INTEGER : leftIndex) -
      (rightIndex === -1 ? Number.MAX_SAFE_INTEGER : rightIndex)
    );
  });

export const getAvailableWaterfallOptions = (
  applied: FilterForm | undefined,
  dataFilters: FilterDataStructure | undefined,
  rawOptions: Option[],
): Option[] => {
  const expandedOptions = expandRawOptionsWithBrandTier(rawOptions, applied);

  if (!expandedOptions.length) {
    return [];
  }

  const hasConcreteBrand = hasSpecificValue(applied?.brands);

  const filtered = expandedOptions.filter((option) => {
    const value = option.value as string;

    if (BRAND_DEPENDENT_WATERFALL_VALUES.has(value) && !hasConcreteBrand) {
      return false;
    }

    const appliedKey = getAppliedKeyForWaterfallFilter(value);
    if (!appliedKey) {
      return true;
    }

    return !hasSpecificValue(applied?.[appliedKey]);
  });

  return sortByWaterfallHierarchy(filtered);
};

const pickFirstAvailable = (
  options: Option[],
  preferredValues: string[],
): string | null => {
  for (const preferred of preferredValues) {
    if (options.some((option) => option.value === preferred)) {
      return preferred;
    }
  }

  return (options[0]?.value as string) ?? null;
};

export const pickHighestInHierarchy = (
  availableOptions: Option[],
  dataFilters: FilterDataStructure | undefined,
  applied: FilterForm,
): string | null => {
  for (const candidate of WATERFALL_VIEW_HIERARCHY) {
    if (
      candidate === 'sub_brand' &&
      hasSingleSubBrand(dataFilters, applied.brands)
    ) {
      continue;
    }

    if (availableOptions.some((option) => option.value === candidate)) {
      return candidate;
    }
  }

  return pickFirstAvailable(availableOptions, []);
};

const getNextInHierarchy = (
  currentView: string,
  availableOptions: Option[],
  dataFilters: FilterDataStructure | undefined,
  postApplied: FilterForm,
): string | null => {
  const currentIndex = WATERFALL_VIEW_HIERARCHY.indexOf(
    currentView as (typeof WATERFALL_VIEW_HIERARCHY)[number],
  );

  if (currentIndex === -1) {
    return pickFirstAvailable(availableOptions, []);
  }

  for (
    let index = currentIndex + 1;
    index < WATERFALL_VIEW_HIERARCHY.length;
    index += 1
  ) {
    const candidate = WATERFALL_VIEW_HIERARCHY[index];

    if (
      candidate === 'sub_brand' &&
      hasSingleSubBrand(dataFilters, postApplied.brands)
    ) {
      continue;
    }

    if (availableOptions.some((option) => option.value === candidate)) {
      return candidate;
    }
  }

  return pickFirstAvailable(availableOptions, []);
};

export const getNextWaterfallFilterAfterDrill = (
  currentView: string,
  postApplied: FilterForm,
  dataFilters: FilterDataStructure | undefined,
  rawOptions: Option[],
  preDrillApplied: FilterForm = postApplied,
): string | null => {
  const expandedOptions = expandRawOptionsWithBrandTier(
    rawOptions,
    postApplied,
  );
  const availableOptions = getAvailableWaterfallOptions(
    postApplied,
    dataFilters,
    expandedOptions,
  );

  if (!availableOptions.length) {
    return null;
  }

  const availableBeforeDrill = getAvailableWaterfallOptions(
    preDrillApplied,
    dataFilters,
    expandRawOptionsWithBrandTier(rawOptions, preDrillApplied),
  );
  const highestBeforeDrill = pickHighestInHierarchy(
    availableBeforeDrill,
    dataFilters,
    preDrillApplied,
  );
  const isOutOfOrderDrill =
    Boolean(highestBeforeDrill) && currentView !== highestBeforeDrill;

  if (isOutOfOrderDrill) {
    return pickHighestInHierarchy(availableOptions, dataFilters, postApplied);
  }

  if (currentView === 'brand' && hasSpecificValue(postApplied.brands)) {
    if (hasSingleSubBrand(dataFilters, postApplied.brands)) {
      return pickFirstAvailable(availableOptions, ['pack_type', 'sku']);
    }
    return 'sub_brand';
  }

  return getNextInHierarchy(
    currentView,
    availableOptions,
    dataFilters,
    postApplied,
  );
};

export function resolveCommercialWaterfallDrillValue(
  waterfallFilter: string,
  clickedLabel: string | string[],
  dataFilters: FilterDataStructure | undefined,
  applied: FilterForm | undefined,
): FilterValue {
  const appliedKey = getAppliedKeyForWaterfallFilter(waterfallFilter);
  const raw = Array.isArray(clickedLabel) ? clickedLabel[0] : clickedLabel;

  if (!appliedKey || raw == null || raw === '') {
    return raw as FilterValue;
  }

  const options = FilterDataAccessor.getInstance().getOptions(
    String(appliedKey),
    dataFilters ?? {},
    applied ?? {},
  ) as Option[];

  const byValue = options.find(
    (option) => String(option.value) === String(raw),
  );
  if (byValue) {
    return byValue.value as FilterValue;
  }

  const byLabel = options.find(
    (option) => String(option.label) === String(raw),
  );
  if (byLabel) {
    return byLabel.value as FilterValue;
  }

  return raw as FilterValue;
}

export const resolveWaterfallFilterOnContextChange = ({
  currentValue,
  availableOptions,
}: {
  currentValue: FilterValue;
  availableOptions: Option[];
}): string | null => {
  const isCurrentValid = availableOptions.some(
    (option) => option.value === currentValue,
  );

  if (isCurrentValid) {
    return currentValue as string;
  }

  return (availableOptions[0]?.value as string) ?? null;
};

export const isGoldenPathComplete = (applied: FilterForm) => {
  return Object.values(WATERFALL_FILTER_TO_APPLIED_KEY)
    .slice(0, -1)
    .every((key) => hasSpecificValue(applied[key]));
};
